+	private scheduleFocusRetry(targetWindow: Window, callback: () => void): IDisposable {
+		let disposed = false;
+		let settled = false;
+		const runOnce = () => {
+			if (!disposed && !settled) {
+				settled = true;
+				callback();
+			}
+		};
