+					rangeStart,
+					rangeEnd,
+					attachment: {
+						type: MessageAttachmentKind.Simple,
+						label: insertText,
+						_meta: toCommandCompletionAttachmentMeta({
+							command: skill.name,
+							description,
+						}),
+					},
+				});
+			}
+		}
+
 		return completionItems.sort((a, b) => a.insertText.localeCompare(b.insertText));
 	}
 }
